# model: evaluate each chain; track gender and parent links
def solve(expr):
    t=expr.split(); names=t[0::2]; ops=t[1::2]
    parent={}; spouse={}; sib={}; g={}
    for a,op,b in zip(names,ops,names[1:]):
        if op=='&': g[a]='M'; sib[a]=b
        if op=='x': g[a]='M'; parent.setdefault(b,set()).add(a)
        if op=='?': g[a]='F'; parent.setdefault(b,set()).add(a)
        if op=='!': g[a]='F'; g[b]='M'; spouse[a]=b; spouse[b]=a
    # propagate: spouse of a parent is also parent; siblings share parents
